CREATE TYPE "LedgerKind" AS ENUM ('XP_AWARD','XP_DEBIT','TRANSFER','ESCROW','REFUND','PAYOUT','PRESTIGE','ADMIN');
CREATE TYPE "GameStatus" AS ENUM ('PENDING','ACTIVE','WON','LOST','DRAW','CANCELLED','EXPIRED');
CREATE TABLE "GuildConfig" ("guildId" TEXT PRIMARY KEY, "version" INTEGER NOT NULL DEFAULT 1, "settings" JSONB NOT NULL, "maintenance" BOOLEAN NOT NULL DEFAULT false, "updatedAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Member" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "userId" TEXT NOT NULL, "xp" INTEGER NOT NULL DEFAULT 0, "lifetimeXp" INTEGER NOT NULL DEFAULT 0, "level" INTEGER NOT NULL DEFAULT 0, "prestige" INTEGER NOT NULL DEFAULT 0, "autoPrestige" BOOLEAN NOT NULL DEFAULT false, "voiceSeconds" BIGINT NOT NULL DEFAULT 0, "frozenUntil" TIMESTAMP(3), "freezeReason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Member_guildId_userId_key" ON "Member"("guildId","userId"); CREATE INDEX "Member_guildId_xp_idx" ON "Member"("guildId","xp"); CREATE INDEX "Member_guildId_voiceSeconds_idx" ON "Member"("guildId","voiceSeconds");
CREATE TABLE "Game" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "type" TEXT NOT NULL, "status" "GameStatus" NOT NULL DEFAULT 'PENDING', "actorUserId" TEXT NOT NULL, "targetUserId" TEXT, "wager" INTEGER NOT NULL DEFAULT 0, "escrow" INTEGER NOT NULL DEFAULT 0, "state" JSONB NOT NULL, "fairness" JSONB, "expiresAt" TIMESTAMP(3), "idempotencyKey" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "Game_idempotencyKey_key" ON "Game"("idempotencyKey"); CREATE INDEX "Game_guildId_status_idx" ON "Game"("guildId","status");
CREATE TABLE "Ledger" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "actorId" TEXT NOT NULL, "targetId" TEXT, "kind" "LedgerKind" NOT NULL, "amount" INTEGER NOT NULL, "balanceAfter" INTEGER NOT NULL, "reason" TEXT NOT NULL, "gameId" TEXT, "idempotencyKey" TEXT NOT NULL, "configVersion" INTEGER NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Ledger_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "Member"("id"), CONSTRAINT "Ledger_targetId_fkey" FOREIGN KEY ("targetId") REFERENCES "Member"("id")); CREATE UNIQUE INDEX "Ledger_idempotencyKey_key" ON "Ledger"("idempotencyKey"); CREATE INDEX "Ledger_guildId_createdAt_idx" ON "Ledger"("guildId","createdAt"); CREATE INDEX "Ledger_actorId_createdAt_idx" ON "Ledger"("actorId","createdAt");
CREATE TABLE "Cooldown" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "userId" TEXT NOT NULL, "key" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "Cooldown_guildId_userId_key_key" ON "Cooldown"("guildId","userId","key");
CREATE TABLE "VoiceSession" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "userId" TEXT NOT NULL, "channelId" TEXT NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL, "lastAccruedAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "VoiceSession_guildId_userId_key" ON "VoiceSession"("guildId","userId");
CREATE TABLE "JobExecution" ("key" TEXT PRIMARY KEY, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), "metadata" JSONB); CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "actorUserId" TEXT, "action" TEXT NOT NULL, "detail" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE "Raffle" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "day" DATE NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN', "result" JSONB); CREATE UNIQUE INDEX "Raffle_guildId_day_key" ON "Raffle"("guildId","day"); CREATE TABLE "QuestProgress" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "userId" TEXT NOT NULL, "questKey" TEXT NOT NULL, "day" DATE NOT NULL, "progress" INTEGER NOT NULL DEFAULT 0, "claimed" BOOLEAN NOT NULL DEFAULT false); CREATE UNIQUE INDEX "QuestProgress_guildId_userId_questKey_day_key" ON "QuestProgress"("guildId","userId","questKey","day"); CREATE TABLE "Bounty" ("id" TEXT PRIMARY KEY, "guildId" TEXT NOT NULL, "creatorUserId" TEXT NOT NULL, "targetUserId" TEXT NOT NULL, "escrow" INTEGER NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN');
